PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
	id INTEGER NOT NULL, 
	email VARCHAR, 
	hashed_password VARCHAR, 
	full_name VARCHAR, 
	is_active BOOLEAN, 
	is_admin BOOLEAN, 
	PRIMARY KEY (id)
);
CREATE TABLE sku_parts (
	id INTEGER NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	sku VARCHAR, 
	name VARCHAR, 
	description VARCHAR, 
	rack_type VARCHAR, 
	tray_type VARCHAR, 
	platform VARCHAR, 
	criticality VARCHAR, 
	annual_demand INTEGER, 
	part_category VARCHAR, 
	PRIMARY KEY (id)
);
CREATE TABLE machine_categories (
	id INTEGER NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	name VARCHAR NOT NULL, 
	description VARCHAR, 
	PRIMARY KEY (id)
);
CREATE TABLE machine_registry (
	id INTEGER NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	category_type VARCHAR NOT NULL, 
	serial_number VARCHAR, 
	brand VARCHAR, 
	model_no VARCHAR, 
	product_type VARCHAR, 
	rack_type VARCHAR, 
	tray_type VARCHAR, 
	platform VARCHAR, 
	criticality VARCHAR, 
	customer VARCHAR, 
	cpu_count VARCHAR, 
	core_count_speed VARCHAR, 
	memory_spec VARCHAR, 
	disk_drives VARCHAR, 
	nic_card VARCHAR, 
	adapter_card VARCHAR, 
	power_supply VARCHAR, 
	tape_drives VARCHAR, 
	network_ports VARCHAR, 
	notes VARCHAR, 
	image_filename VARCHAR, 
	price_usd FLOAT, 
	conversion_rate FLOAT, 
	price_myr FLOAT, 
	lead_time_days INTEGER, 
	holding_cost_percentage FLOAT, 
	annual_demand INTEGER, 
	shipping_cost FLOAT, 
	PRIMARY KEY (id)
);
CREATE TABLE config (
	id INTEGER NOT NULL, 
	email_sender VARCHAR, 
	smtp_server VARCHAR, 
	smtp_port INTEGER, 
	smtp_use_tls BOOLEAN, 
	smtp_username VARCHAR, 
	smtp_password VARCHAR, 
	notification_email VARCHAR, 
	default_conversion_rate FLOAT, 
	PRIMARY KEY (id)
);
CREATE TABLE sku_part_meta (
	id INTEGER NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	sku_id INTEGER NOT NULL, 
	customer_usage VARCHAR, 
	image_filename VARCHAR, 
	PRIMARY KEY (id), 
	FOREIGN KEY(sku_id) REFERENCES sku_parts (id)
);
CREATE TABLE part_items (
	id INTEGER NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	sku_id INTEGER NOT NULL, 
	vendor VARCHAR, 
	serial_no VARCHAR, 
	description VARCHAR, 
	outgoing_flag BOOLEAN, 
	returning_flag BOOLEAN, 
	date_out DATETIME, 
	price_usd FLOAT, 
	price_myr FLOAT, 
	conversion_rate FLOAT, 
	customer VARCHAR, 
	engineer VARCHAR, 
	remarks VARCHAR, 
	lead_time_days INTEGER, 
	unit_cost FLOAT, 
	holding_cost_percentage FLOAT, 
	annual_demand INTEGER, 
	shipping_cost FLOAT, 
	eoq_min_threshold INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(sku_id) REFERENCES sku_parts (id)
);
CREATE TABLE activity_logs (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	action VARCHAR, 
	part_id INTEGER, 
	description VARCHAR, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(part_id) REFERENCES sku_parts (id)
);
CREATE TABLE client_faulty_logs (
	id INTEGER NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	user_id INTEGER, 
	part_id INTEGER, 
	client_name VARCHAR, 
	engineer_name VARCHAR, 
	part_no VARCHAR, 
	part_description VARCHAR, 
	serial_no VARCHAR, 
	part_status VARCHAR, 
	remark VARCHAR, 
	ticket_no VARCHAR, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(part_id) REFERENCES sku_parts (id)
);
CREATE TABLE sku_part_machine_categories (
	id INTEGER NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	sku_id INTEGER NOT NULL, 
	machine_category_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(sku_id) REFERENCES sku_parts (id), 
	FOREIGN KEY(machine_category_id) REFERENCES machine_categories (id)
);
CREATE TABLE machine_registry_serials (
	id INTEGER NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	registry_id INTEGER NOT NULL, 
	serial_no VARCHAR NOT NULL, 
	outgoing_flag BOOLEAN, 
	date_out DATETIME, 
	customer VARCHAR, 
	engineer VARCHAR, 
	remarks VARCHAR, 
	ticket_no VARCHAR, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_machine_registry_serial UNIQUE (registry_id, serial_no), 
	FOREIGN KEY(registry_id) REFERENCES machine_registry (id)
);
CREATE UNIQUE INDEX ix_users_email ON users (email);
CREATE INDEX ix_users_id ON users (id);
CREATE INDEX ix_sku_parts_sku ON sku_parts (sku);
CREATE INDEX ix_sku_parts_id ON sku_parts (id);
CREATE INDEX ix_sku_parts_name ON sku_parts (name);
CREATE UNIQUE INDEX ix_machine_categories_name ON machine_categories (name);
CREATE INDEX ix_machine_categories_id ON machine_categories (id);
CREATE INDEX ix_machine_registry_category_type ON machine_registry (category_type);
CREATE INDEX ix_machine_registry_serial_number ON machine_registry (serial_number);
CREATE INDEX ix_machine_registry_id ON machine_registry (id);
CREATE INDEX ix_machine_registry_model_no ON machine_registry (model_no);
CREATE INDEX ix_config_id ON config (id);
CREATE UNIQUE INDEX ix_sku_part_meta_sku_id ON sku_part_meta (sku_id);
CREATE INDEX ix_sku_part_meta_id ON sku_part_meta (id);
CREATE INDEX ix_part_items_serial_no ON part_items (serial_no);
CREATE INDEX ix_part_items_id ON part_items (id);
CREATE INDEX ix_part_items_sku_id ON part_items (sku_id);
CREATE INDEX ix_activity_logs_id ON activity_logs (id);
CREATE INDEX ix_activity_logs_action ON activity_logs (action);
CREATE INDEX ix_client_faulty_logs_serial_no ON client_faulty_logs (serial_no);
CREATE INDEX ix_client_faulty_logs_client_name ON client_faulty_logs (client_name);
CREATE INDEX ix_client_faulty_logs_part_no ON client_faulty_logs (part_no);
CREATE INDEX ix_client_faulty_logs_ticket_no ON client_faulty_logs (ticket_no);
CREATE INDEX ix_client_faulty_logs_id ON client_faulty_logs (id);
CREATE UNIQUE INDEX ix_sku_part_machine_categories_sku_id ON sku_part_machine_categories (sku_id);
CREATE INDEX ix_sku_part_machine_categories_id ON sku_part_machine_categories (id);
CREATE INDEX ix_sku_part_machine_categories_machine_category_id ON sku_part_machine_categories (machine_category_id);
CREATE INDEX ix_machine_registry_serials_serial_no ON machine_registry_serials (serial_no);
CREATE INDEX ix_machine_registry_serials_registry_id ON machine_registry_serials (registry_id);
CREATE INDEX ix_machine_registry_serials_id ON machine_registry_serials (id);
COMMIT;
